-- Francouzské názvy a popisy surovin pro katalog na webu (/fr/suroviny).
-- Přeloženo z českých řádků food_translations; appka sama je nevyrábí,
-- nová surovina v appce spadne na webu na angličtinu (viz src/lib/foods.ts).
-- Idempotentní: řádek se vloží jen tam, kde francouzský překlad ještě není.

insert into public.food_translations (food_id, locale, name, description)
select v.food_id::uuid, 'fr', v.name, v.description
from (values
  ('29309265-98fe-48df-ab2b-cf366109d04a', $t$Anchois$t$, $t$Anchois – petits poissons gras de mer riches en oméga-3 et en calcium (se mangent entiers). À utiliser frais/congelés, pas salés. Poisson gras de mer, précieuse source d'oméga-3 et de vitamine D. À donner 1 à 2 fois par semaine.$t$),
  ('a0000006-0000-0000-0000-000000000003', $t$Banane$t$, $t$Banane – fruit sucré riche en potassium. En très petite quantité. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('c689b537-46e6-45e2-9afc-a310893e6d7c', $t$Patate douce$t$, $t$Patate douce – source de fibres et de bêta-carotène. À servir cuite. Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('6051e9b5-863b-4631-8ad4-3e5dda636b4c', $t$Yaourt nature$t$, $t$Yaourt nature – probiotiques et calcium. En petite quantité. Complément laitier – en petite quantité seulement, certains chiens digèrent mal le lactose. Source de protéines et de calcium.$t$),
  ('a0000006-0000-0000-0000-000000000002', $t$Myrtilles$t$, $t$Myrtilles – antioxydants, petite friandise idéale. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('a0000005-0000-0000-0000-000000000002', $t$Brocoli$t$, $t$Brocoli – crucifère riche en vitamine C. En petite quantité seulement. Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('fb1b6b73-6cf9-4060-85bc-f747d54d384a', $t$Céleri branche$t$, $t$Céleri branche – légume juteux, peu calorique et riche en fibres. À hacher finement ou à mixer (tiges fibreuses). Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('76ebab08-3cc8-4db3-af20-febdb22d4b50', $t$Cassis$t$, $t$Cassis – baies noires à la teneur exceptionnelle en vitamine C. Ribes, pas du raisin – sans danger en petite quantité. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('6f014bae-e624-452e-a44e-c19e35e86d05', $t$Groseilles rouges$t$, $t$Groseilles rouges – baies acidulées riches en vitamine C et en fibres. La groseille (Ribes) n'est pas du raisin ; sans danger pour les chiens en petite quantité. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('a0000005-0000-0000-0000-000000000003', $t$Courgette$t$, $t$Courgette – légume léger, bien digeste et peu calorique. Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('0c85323f-f4b7-420d-aeee-f5075540d621', $t$Viande de daim$t$, $t$Viande de daim – gibier maigre. Base de la ration – représente 50 à 70 % de la partie carnée. Si le gibier ne vient pas d'une source vérifiée (par ex. du supermarché), mieux vaut le cuire.$t$),
  ('702a5427-731f-4730-8f64-7efd6289ac10', $t$Sanglier$t$, $t$Sanglier – viande de gibier foncée. À congeler à cause de la maladie d'Aujeszky et des trichines. Base de la ration – représente 50 à 70 % de la partie carnée. Si le gibier ne vient pas d'une source vérifiée (par ex. du supermarché), mieux vaut le cuire.$t$),
  ('16d2ff5e-eadc-4bfd-ad6b-081e7b14cc9a', $t$Potiron$t$, $t$Potiron – fibres douces, favorise la digestion. À servir cuit. Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('19aea7c3-4afb-4e44-9713-577739581ec8', $t$Panse de bœuf$t$, $t$Panse de bœuf – la panse verte non lavée favorise la digestion et le microbiome. Estomac (panse) – verte et non lavée, elle est excellente pour la digestion et le microbiome. Compte dans la viande musculaire.$t$),
  ('a0000004-0000-0000-0000-000000000002', $t$Foie de bœuf$t$, $t$Foie de bœuf – la source de foie classique et la plus courante en BARF. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('e1b1a750-4fbf-4aae-9268-48e42b6799b6', $t$Langue de bœuf$t$, $t$Langue de bœuf – viande musculaire plus grasse, compte dans la viande. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('a0000003-0000-0000-0000-000000000003', $t$Rognons de bœuf$t$, $t$Rognons de bœuf – organe sécréteur riche en sélénium et en vitamines B. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('d5b54d70-b04c-4e41-b3f8-e6cf43a8b0a8', $t$Joues de bœuf$t$, $t$Joues de bœuf – muscle de travail, maigre et juteux. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('dfe72b7d-72a0-46b2-a91e-9363997b2a49', $t$Os à moelle de bœuf$t$, $t$Os à moelle de bœuf – os porteur très dur, uniquement à ronger. Os porteur plus dur – plutôt à ronger qu'à consommer. TOUJOURS cru, surveillez l'usure des dents.$t$),
  ('1395dd80-e114-4772-af5b-27900c91b465', $t$Cervelle de bœuf$t$, $t$Cervelle de bœuf – source de bonnes graisses et de DHA. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('f3249739-7cd5-4a86-a39d-f724e019a0e6', $t$Queue de bœuf$t$, $t$Queue de bœuf – os charnu avec cartilage, source de collagène. Os porteur plus dur – plutôt à ronger qu'à consommer. TOUJOURS cru, surveillez l'usure des dents.$t$),
  ('a0000003-0000-0000-0000-000000000004', $t$Poumon de bœuf$t$, $t$Poumon de bœuf – organe léger et maigre. À donner en complément de la partie carnée, apprécié aussi séché comme friandise.$t$),
  ('aaf196f4-c2ea-4251-bf7a-a286ed463234', $t$Trachée de bœuf$t$, $t$Trachée de bœuf – cartilage riche en glucosamine, excellente friandise à mâcher. Partie cartilagineuse – source naturelle de glucosamine et de chondroïtine pour les articulations. Friandise à mâcher très appréciée.$t$),
  ('9acb18fb-345e-4b90-9dfa-1572ee0d4c80', $t$Rate de bœuf$t$, $t$Rate de bœuf – organe sécréteur très riche en fer. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('3f9c2160-688e-4799-8c46-e968d7098af8', $t$Pancréas de bœuf$t$, $t$Pancréas de bœuf – organe sécréteur, enzymes naturelles (adapté en cas d'IPE). Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('a0000003-0000-0000-0000-000000000002', $t$Cœur de bœuf$t$, $t$Cœur de bœuf – excellente source de taurine, abordable. Organe musculaire riche en taurine – compte dans la viande musculaire, pas dans les abats. Jusqu'à 10 à 15 % de la ration.$t$),
  ('a0000001-0000-0000-0000-000000000002', $t$Viande musculaire de bœuf$t$, $t$Viande musculaire de bœuf – la viande maigre de base de la ration BARF. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('56778459-2e46-48e7-bc0b-9c66363f028a', $t$Pis de vache$t$, $t$Pis de vache – viande musculaire complémentaire grasse. Compte dans la viande musculaire, pas dans les abats – il n'a ni vitamine A, ni cuivre, ni sélénium comme le foie ou les rognons. Peu de protéines et beaucoup de gras, donc seulement pour varier – il ne remplace pas la viande de bœuf.$t$),
  ('45ce601b-9401-40c7-bbce-cd0e0be3e84e', $t$Poire$t$, $t$Poire – fruit juteux riche en fibres. Sans le trognon. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('adfbf92d-ab6a-4667-8bbb-c4f11c9456d1', $t$Foie d'oie$t$, $t$Foie d'oie – gras et riche, en petite quantité seulement. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('50cd76c8-593c-4209-adf0-288ddacdc443', $t$Cous d'oie$t$, $t$Cous d'oie – gros os comestible, plus gras. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('1ac34fa5-d58e-4174-8e68-4d60bd04719a', $t$Viande d'oie$t$, $t$Viande d'oie – volaille plus grasse, goût prononcé. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('a0000006-0000-0000-0000-000000000001', $t$Pomme$t$, $t$Pomme – source de fibres et de vitamine C. Retirez le trognon (les pépins contiennent du cyanure). Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('2bf512d2-fe48-40b4-a185-3148bbf4b741', $t$Fraises$t$, $t$Fraises – vitamine C et fibres, en friandise. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('7164342c-b939-45eb-b9aa-871d02c062e8', $t$Foie d'agneau$t$, $t$Foie d'agneau – riche en cuivre et en vitamine A. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('d35ddd87-a7b9-43cf-9455-3ab48b9c9ee6', $t$Langue d'agneau$t$, $t$Langue d'agneau – viande musculaire plus grasse. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('ee19cd47-c739-4e64-a446-b33795e3d842', $t$Rognons d'agneau$t$, $t$Rognons d'agneau – rognons plus petits, plus fins. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('a0000001-0000-0000-0000-000000000004', $t$Viande d'agneau$t$, $t$Viande d'agneau – viande rouge plus grasse au goût prononcé. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('07e8641d-d73b-44d1-b437-057fbde6e71b', $t$Poumon d'agneau$t$, $t$Poumon d'agneau – organe léger, friandise séchée appréciée. Organe léger et maigre. À donner en complément de la partie carnée, apprécié aussi séché comme friandise.$t$),
  ('f925dca9-49b2-4c90-a1a9-ed4fb158c7bd', $t$Cœur d'agneau$t$, $t$Cœur d'agneau – cœur plus petit, idéal pour les chiens moyens. Organe musculaire riche en taurine – compte dans la viande musculaire, pas dans les abats. Jusqu'à 10 à 15 % de la ration.$t$),
  ('3c87d0ca-fee4-45ac-853a-bc90a308dcef', $t$Côtes d'agneau$t$, $t$Côtes d'agneau – os comestible avec une couche de viande et de gras. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('fc9b60eb-dc25-43c2-bae7-6e5502792888', $t$Foie de cerf$t$, $t$Foie de cerf – foie de gibier, riche en nutriments. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('ed329b3b-fb4e-41cb-b303-1da314174fc4', $t$Foie de canard$t$, $t$Foie de canard – foie de volaille plus gras. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('c74f3c78-af49-48a4-9eee-590b7eacc587', $t$Ailes de canard$t$, $t$Ailes de canard – os comestible charnu. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('a0000002-0000-0000-0000-000000000003', $t$Cous de canard$t$, $t$Cous de canard – os comestible plus gros pour chiens moyens et grands. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('a0000001-0000-0000-0000-000000000005', $t$Poitrine de canard$t$, $t$Poitrine de canard – viande de volaille foncée, plus maigre. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('a4f6cd41-cea7-4fa5-adfc-3b11c0b64dc0', $t$Carcasses de canard$t$, $t$Carcasses de canard – carcasse plus grasse avec cartilage. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('2e3cc505-ceb6-4c91-87c7-efbaba617d87', $t$Cœurs de canard$t$, $t$Cœurs de canard – petit organe musculaire riche en taurine. Organe musculaire riche en taurine – compte dans la viande musculaire, pas dans les abats. Jusqu'à 10 à 15 % de la ration.$t$),
  ('53361084-adb1-43de-8ac2-ac73025ccd1c', $t$Gésiers de canard$t$, $t$Gésiers de canard – musclés et savoureux. Gésier musculeux, compte dans la viande musculaire. Naturellement riche en protéines.$t$),
  ('8a817089-1223-4042-8ea3-e01e0e265b78', $t$Foie de cheval$t$, $t$Foie de cheval – maigre et riche en fer. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('e36871a2-7e20-4c68-90d9-0df96ec31118', $t$Viande de cheval$t$, $t$Viande de cheval – maigre, hypoallergénique, adaptée en cas d'allergies. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('f81d67a3-a49e-49f3-af72-27ee577c3ed0', $t$Cœur de cheval$t$, $t$Cœur de cheval – organe musculaire maigre. Organe musculaire riche en taurine – compte dans la viande musculaire, pas dans les abats. Jusqu'à 10 à 15 % de la ration.$t$),
  ('1f48fd0f-78a3-4091-8c7b-49e39bc39c3c', $t$Viande de chèvre$t$, $t$Viande de chèvre – viande rouge maigre, peu allergène. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('0236d8aa-8504-4618-94ea-a37b83a6a572', $t$Foie de lapin$t$, $t$Foie de lapin – foie maigre d'une viande maigre. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('1ef4deb1-21c7-44a0-9215-8d6350bf5d6b', $t$Viande de lapin$t$, $t$Viande de lapin – maigre et facile à digérer, hypoallergénique. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('53081f21-372e-44e9-87bb-d933f5f475e1', $t$Lapin entier (avec os)$t$, $t$Lapin entier avec os – proie complète : viande musculaire, os comestibles et abats réunis. L'appli le répartit grosso modo en 60 % de viande musculaire, 30 % d'os et 10 % d'abats. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('dc010526-9f58-49cb-8ff1-adb082496379', $t$Caille (entière)$t$, $t$Caille entière – petite proie complète, avec os et organes. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('20e99202-683d-4dce-97ce-7e29b616f3e1', $t$Foie de dinde$t$, $t$Foie de dinde – source de foie de volaille. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('68f7535a-d943-4647-92b2-ae4116ca009f', $t$Ailes de dinde$t$, $t$Ailes de dinde – os comestible charnu pour les grands chiens. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('c4e9cc16-dd6a-4fef-b83e-2bcf2a6cf127', $t$Cous de dinde$t$, $t$Cous de dinde – gros os comestible pour les grands chiens. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('a0000001-0000-0000-0000-000000000003', $t$Blanc de dinde$t$, $t$Blanc de dinde – viande blanche très maigre. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('c416d378-17da-493a-a961-4346c65ca704', $t$Cœur de dinde$t$, $t$Cœur de dinde – organe musculaire riche en taurine. Organe musculaire riche en taurine – compte dans la viande musculaire, pas dans les abats. Jusqu'à 10 à 15 % de la ration.$t$),
  ('45c82f5d-99ad-4f15-b714-2ba229bf308d', $t$Cuisse de dinde$t$, $t$Cuisse de dinde – viande plus foncée, un peu plus grasse. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('8c2ad4ff-590b-49d4-ad24-00c4ddf6425c', $t$Gésiers de dinde$t$, $t$Gésiers de dinde – organe musclé, compte dans la viande musculaire. Gésier musculeux, compte dans la viande musculaire. Naturellement riche en protéines.$t$),
  ('a0000002-0000-0000-0000-000000000002', $t$Dos de poulet$t$, $t$Dos de poulet avec cartilage et restes de viande. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('a0000004-0000-0000-0000-000000000001', $t$Foie de poulet$t$, $t$Foie de poulet – tendre et facile à trouver, adapté aux petits chiens. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('6fa17f82-6bfe-4071-b9ff-eaf134ded315', $t$Ailes de poulet$t$, $t$Ailes de poulet – os comestible bien digeste. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('a0000002-0000-0000-0000-000000000001', $t$Cous de poulet$t$, $t$Cous de poulet tendres, os comestible idéal pour les petits et moyens chiens. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('e7d8fcb4-ae47-46c1-89ec-f4324a565e4c', $t$Pattes de poulet$t$, $t$Pattes de poulet – source naturelle de glucosamine, friandise appréciée. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('a0000001-0000-0000-0000-000000000001', $t$Blanc de poulet$t$, $t$Blanc de poulet – viande blanche maigre, base pour les chiens sensibles. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('8086894d-8fb1-4590-bcf2-a88b9cede648', $t$Carcasses de poulet$t$, $t$Carcasses de poulet (squelettes) après désossage, avec cartilage et restes de viande. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
