  ('a824dddb-fd60-4bb3-870c-c2f9501de3ad', $t$Gésiers de poulet$t$, $t$Gésiers de poulet – musclés, comptent dans la viande musculaire. Gésier musculeux, compte dans la viande musculaire. Naturellement riche en protéines.$t$),
  ('7f31950d-8120-4e40-a229-5937b1731d79', $t$Chou-fleur$t$, $t$Chou-fleur – crucifère riche en vitamine C et en folates. De préférence légèrement cuit à la vapeur. Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('b6e5ab5e-544b-4e68-9490-0d1c1c79bee5', $t$Saumon$t$, $t$Saumon – poisson gras riche en oméga-3. Congelé au moins 3 semaines à cause des parasites. Poisson gras de mer, précieuse source d'oméga-3 et de vitamine D. À donner 1 à 2 fois par semaine.$t$),
  ('a0000007-0000-0000-0000-000000000001', $t$Huile de saumon$t$, $t$Huile de saumon – source liquide d'oméga-3 pour le poil et les articulations. Complément en acides gras oméga-3 pour le poil et les articulations. Quelques gouttes à quelques ml par jour selon la taille du chien.$t$),
  ('0ebe106b-b2c4-4273-937a-3f34bdd94f3b', $t$Maquereau$t$, $t$Maquereau – poisson gras de mer riche en oméga-3. Poisson gras de mer, précieuse source d'oméga-3 et de vitamine D. À donner 1 à 2 fois par semaine.$t$),
  ('0943f697-a6db-4de0-baf6-62df039a0328', $t$Framboises$t$, $t$Framboises – baies riches en fibres et en vitamine C. En petite quantité seulement (traces de xylitol). Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('4d946245-2f63-4a2b-876b-53c526b7384b', $t$Coquille d'œuf moulue$t$, $t$Coquille d'œuf moulue – calcium pur pour les rations sans os. Complément de calcium pour les rations sans os. Env. 1 g (½ cuillère à café) pour 500 g de viande.$t$),
  ('5d14b3ac-b118-4cb2-8a3a-0625ee499265', $t$Algue marine$t$, $t$Algue marine – source naturelle d'iode. Juste une pincée. Source naturelle d'iode pour la thyroïde. Juste une pincée – le surdosage en iode est vite arrivé.$t$),
  ('a0000005-0000-0000-0000-000000000001', $t$Carotte$t$, $t$Carotte – bêta-carotène et fibres, appréciée aussi crue à croquer. Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('1dc17ceb-c3cb-4328-af14-51131bc06525', $t$Mûres$t$, $t$Mûres – baies noires riches en antioxydants et en fibres. Petite friandise idéale. Fruit uniquement en friandise occasionnelle et en petite quantité, à cause du sucre.$t$),
  ('b2f1e6a4-7c3d-4b8e-9a12-5f7c9d0e1a23', $t$Poireau$t$, $t$Poireau – légume du genre Allium. ATTENTION : le poireau est toxique pour les chiens (comme l'oignon et l'ail) – il endommage les globules rouges et peut provoquer une anémie hémolytique. Déconseillé, même cuit.$t$),
  ('c815843e-9614-4cb4-bd19-df93b3f0726d', $t$Algue nori$t$, $t$Algue nori – algue marine riche en iode et en vitamine A, plus douce que le kelp. À donner en petite quantité seulement. Source naturelle d'iode pour la thyroïde. Petite quantité seulement – le surdosage en iode est vite arrivé.$t$),
  ('b1668561-d079-4ee0-a6b7-df9ccf3286dd', $t$Sardines$t$, $t$Sardines – petits poissons de mer, entiers avec les arêtes. Poisson gras de mer, précieuse source d'oméga-3 et de vitamine D. À donner 1 à 2 fois par semaine.$t$),
  ('d3c9da3b-e70e-42f7-b815-f019d1d97461', $t$Hareng$t$, $t$Hareng – poisson gras de mer, source d'oméga-3 et de vitamine D. Poisson gras de mer, précieuse source d'oméga-3 et de vitamine D. À donner 1 à 2 fois par semaine.$t$),
  ('a0000005-0000-0000-0000-000000000004', $t$Épinards$t$, $t$Épinards – légume-feuille riche en fer. Avec modération (oxalates). Légume – env. 10 % de la ration. Pour une meilleure digestibilité, mixer ou cuire légèrement à la vapeur.$t$),
  ('8c40218d-0b9e-49c5-b376-34b3dd3e58bf', $t$Viande de chevreuil$t$, $t$Viande de chevreuil – gibier fin et maigre. Base de la ration – représente 50 à 70 % de la partie carnée. Si le gibier ne vient pas d'une source vérifiée (par ex. du supermarché), mieux vaut le cuire.$t$),
  ('4258ea8a-cbdb-4349-9b8b-c5714717f8f0', $t$Foie de veau$t$, $t$Foie de veau – plus fin et plus léger que le foie de bœuf. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('f1085f36-49e8-4bf6-93e6-206687616f05', $t$Viande musculaire de veau$t$, $t$Viande musculaire de veau – viande fine et maigre. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('17da90b5-de38-41bd-bbe7-e0a4efb2ec67', $t$Fromage blanc$t$, $t$Fromage blanc – protéines légères et calcium. Complément laitier – en petite quantité seulement, certains chiens digèrent mal le lactose. Source de protéines et de calcium.$t$),
  ('a0000007-0000-0000-0000-000000000002', $t$Œuf$t$, $t$Œuf – protéine complète ; avec la coquille, source de calcium aussi. Œuf entier avec sa coquille – protéine complète et calcium. 2 à 3 fois par semaine selon la taille du chien.$t$),
  ('6dff6fc2-dfdd-40cb-9de2-4ac3864885c3', $t$Hampe de porc$t$, $t$Hampe de porc – muscle fin du diaphragme, viande musculaire savoureuse. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('bb8a8f3d-c79d-4ee3-a03b-40943c8e46bb', $t$Tête de porc$t$, $t$Tête de porc – viande, cartilage et os réunis. Os porteur plus dur – plutôt à ronger qu'à consommer. TOUJOURS cru, surveillez l'usure des dents.$t$),
  ('5cfdf04b-cfba-4cd7-b52e-0dcb6a3844f1', $t$Foie de porc$t$, $t$Foie de porc – source de foie facile à trouver, goût prononcé. L'organe le plus important du BARF, extrêmement riche en vitamine A, cuivre et fer. Max. 5 % de la ration, sinon risque de surdosage en vitamine A.$t$),
  ('af918a13-86cd-4a50-bac8-88b550b4a5a9', $t$Échine de porc$t$, $t$Échine de porc – morceau plus juteux et plus persillé. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('835bf3b4-0ed7-41f5-a780-0acaef4c3590', $t$Cuisse de porc$t$, $t$Cuisse de porc – morceau arrière plus maigre. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('59676165-74e0-4e97-993e-2ce4aa470717', $t$Joues de porc$t$, $t$Joues de porc – muscle de travail juteux. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('80f5f491-4091-4b6f-8a93-b30db86cc90a', $t$Os à moelle de porc$t$, $t$Os à moelle de porc – os porteur dur, à ronger. Os porteur plus dur – plutôt à ronger qu'à consommer. TOUJOURS cru, surveillez l'usure des dents.$t$),
  ('754de29a-cd26-406f-86cd-2c5a82d8ea5d', $t$Filet mignon de porc$t$, $t$Filet mignon de porc – le morceau de porc le plus maigre. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('0e056f3b-1cb6-4453-bf8d-1e6029246a46', $t$Longe de porc (côtelette)$t$, $t$Longe de porc (côtelette) – viande maigre du dos. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('c6d2374c-71f7-4f34-a816-f259c96e7448', $t$Épaule de porc$t$, $t$Épaule de porc – morceau moyennement gras. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('1588c11d-3a4d-4ee7-bdb8-13999488b15c', $t$Rate de porc$t$, $t$Rate de porc – organe riche en fer. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('381853bc-32bc-4e3c-842c-f588fd652fd7', $t$Pancréas de porc$t$, $t$Pancréas de porc – source d'enzymes digestives. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('d5b2b7e3-34e8-4846-812b-da1ea3131e01', $t$Viande musculaire de porc$t$, $t$Viande musculaire de porc – viande de porc en général. Toujours bien congelée (Aujeszky). Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('cc786e81-634e-4aba-acf1-de134cd83850', $t$Travers de porc$t$, $t$Travers de porc – os comestible charnu. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('4224fc51-d21a-4c08-ad09-2e20d29f6bec', $t$Jarret de porc$t$, $t$Jarret de porc – os porteur plus dur avec de la viande. Os porteur plus dur – plutôt à ronger qu'à consommer. TOUJOURS cru, surveillez l'usure des dents.$t$),
  ('876caa4e-47a0-4ac0-b524-2f5d72aacb97', $t$Rognons de porc$t$, $t$Rognons de porc – organe sécréteur facile à trouver. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('01ffd839-64be-4c08-b7e6-05e49bbc9961', $t$Pieds de porc$t$, $t$Pieds de porc – peau, cartilage et os, source de collagène. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('79930f0f-64d7-4f43-a080-8b0f7e2dbd8f', $t$Poumon de porc$t$, $t$Poumon de porc – organe léger et maigre. À donner en complément de la partie carnée, apprécié aussi séché comme friandise.$t$),
  ('ef60c485-97b6-4285-b971-92663e5dfd57', $t$Saindoux$t$, $t$Saindoux – graisse animale pure, énergie concentrée. Graisse pure – source d'énergie concentrée. À utiliser avec modération, surtout pour les chiens actifs ou dénutris.$t$),
  ('b5129d74-6082-416d-a926-d3512ebd7381', $t$Cœur de porc$t$, $t$Cœur de porc – organe musculaire riche en taurine. Organe musculaire riche en taurine – compte dans la viande musculaire, pas dans les abats. Jusqu'à 10 à 15 % de la ration.$t$),
  ('4746ff20-9eb2-49c5-a856-bf10ed381957', $t$Oreilles de porc$t$, $t$Oreilles de porc – friandise cartilagineuse à ronger. Partie cartilagineuse – source naturelle de glucosamine et de chondroïtine pour les articulations. Friandise à mâcher très appréciée.$t$),
  ('b50e8776-88e4-41b9-b0bd-8898b0de24a7', $t$Ris de porc$t$, $t$Ris de porc – organe sécréteur glandulaire au goût délicat. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('3b5e40a9-b3d2-438d-b49f-bb8bede65120', $t$Poitrine de porc$t$, $t$Poitrine de porc – morceau très gras, énergétique. Avec modération. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('6c21434d-854d-405e-831b-54fe8eb33d95', $t$Langue de porc$t$, $t$Langue de porc – viande musculaire plus grasse. Base de la ration – représente 50 à 70 % de la partie carnée.$t$),
  ('e7b543db-0607-4c85-b4a5-eb47289b8784', $t$Cervelle de porc$t$, $t$Cervelle de porc – riche en graisses et en DHA. Organe sécréteur (abats). Représente avec le foie env. 10 % de la ration, dont ~5 % d'organes autres que le foie.$t$),
  ('c3268866-3fc0-45ad-86d3-546ad12c8d3f', $t$Queue de porc$t$, $t$Queue de porc – os comestible gras avec cartilage. Os charnu tendre et comestible – source de calcium. Représente env. 10 à 15 % de la ration. TOUJOURS cru, jamais cuit (les os cuits se fendent en éclats).$t$),
  ('6e8b6695-b121-4fa1-b17e-9fce79b614d1', $t$Estomac de porc$t$, $t$Estomac de porc – organe musclé, soutient la digestion. Estomac (panse) – verte et non lavée, elle est excellente pour la digestion et le microbiome. Compte dans la viande musculaire.$t$),
  ('914c4da0-4e64-4384-b334-59fdbf8516db', $t$Gibier (cerf)$t$, $t$Gibier (cerf) – viande foncée et maigre. Base de la ration – représente 50 à 70 % de la partie carnée. Si le gibier ne vient pas d'une source vérifiée (par ex. du supermarché), mieux vaut le cuire.$t$)
) as v(food_id, name, description)
where not exists (
  select 1 from public.food_translations t where t.food_id = v.food_id::uuid and t.locale = 'fr'
);
